package com.fitmind.service;
import com.fitmind.entity.*; import com.fitmind.enums.WeightUnit; import com.fitmind.vo.DashboardOverviewVO; import org.junit.jupiter.api.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class DashboardServiceTest { ProfileService profile=mock(ProfileService.class);WeightService weights=mock(WeightService.class);HealthLetterService letters=mock(HealthLetterService.class);DashboardService service=new DashboardService(profile,weights,letters);@BeforeEach void init(){UserProfile p=new UserProfile();p.setStartWeightKg(new BigDecimal("61.90"));p.setTargetWeightKg(new BigDecimal("52.50"));p.setPreferredWeightUnit(WeightUnit.jin);when(profile.get()).thenReturn(p);when(weights.trend(7)).thenReturn(Arrays.asList(w("2026-08-06","56.95"),w("2026-08-12","56.80")));}@Test void values(){DashboardOverviewVO v=service.overview();assertEquals(new BigDecimal("56.80"),v.getCurrentWeightKg());assertEquals(new BigDecimal("4.30"),v.getDistanceToTargetKg());assertEquals(new BigDecimal("-0.15"),v.getChange7dKg());assertEquals(new BigDecimal("54.3"),v.getProgressPercent());}@Test void empty(){when(weights.trend(7)).thenReturn(Collections.emptyList());assertNotNull(service.overview().getCurrentWeightKg());} static WeightRecord w(String d,String v){WeightRecord r=new WeightRecord();r.setRecordDate(LocalDate.parse(d));r.setWeightKg(new BigDecimal(v));return r;} }
